const envelope = $json.body;
if (!envelope || Array.isArray(envelope) || typeof envelope !== 'object') throw new Error('customer envelope required');
if (Object.keys(envelope).sort().join(',') !== 'customer_auth,intent') throw new Error('bounded envelope required');
const input = envelope.intent;
const proof = envelope.customer_auth;
const allowed = new Set(['contract','surface','external_account_reference','provider_event_id','external_order_reference','customer_conversation_id','items','customer','note']);
if (!input || Object.keys(input).some(k => !allowed.has(k))) throw new Error('unsupported intent fields');
if (input.contract !== 'autobiz.customer-order-intent.v1' || input.surface !== 'telegram') throw new Error('unsupported customer contract');
function text(value, max) {
  if (typeof value !== 'string' || !value.trim() || value.length > max || /[\u0000-\u001f\u007f]/.test(value)) throw new Error('invalid bounded customer field');
}
for (const key of ['external_account_reference','provider_event_id','external_order_reference','customer_conversation_id']) text(input[key],255);
if (!Array.isArray(input.items) || input.items.length < 1 || input.items.length > 20) throw new Error('invalid bounded items');
for (const item of input.items) {
  if (!item || Object.keys(item).some(k => !['sku','variant','quantity'].includes(k))) throw new Error('unsupported item fields');
  text(item.sku,50); text(item.variant,100);
  if (!Number.isInteger(item.quantity) || item.quantity < 1 || item.quantity > 1000) throw new Error('invalid quantity');
}
if (!input.customer || Object.keys(input.customer).some(k => !['name','phone','address','reference'].includes(k))) throw new Error('invalid customer fields');
for (const [key,max] of [['name',255],['phone',50],['address',1000]]) text(input.customer[key],max);
if (input.customer.reference !== undefined) text(input.customer.reference,255);
if (input.note !== undefined) text(input.note,1000);
if (!proof || Object.keys(proof).sort().join(',') !== 'created,signature' || !Number.isSafeInteger(proof.created) || !/^[0-9a-f]{64}$/.test(proof.signature)) throw new Error('invalid customer proof');
function stable(v) {
  if (Array.isArray(v)) return '[' + v.map(stable).join(',') + ']';
  if (v && typeof v === 'object') return '{' + Object.keys(v).sort().map(k => JSON.stringify(k) + ':' + stable(v[k])).join(',') + '}';
  return JSON.stringify(v);
}
const body = stable(envelope);
if (Buffer.byteLength(body,'utf8') > 8192) throw new Error('customer envelope too large');
return [{json:{method:'POST',path:'/v1/integration/customer-order-intents',content_type:'application/json',body,security_profile:'RFC9421_HMAC_SHA256_V1',direction:'N8N_TO_CORE'}}];

const result = $json;
const input = JSON.parse($('Normalize bounded customer intent').item.json.body).intent;
if (!result || result.status !== 'DRAFT_CREATED' || result.draft_status !== 'draft' || result.external_order_reference !== input.external_order_reference) throw new Error('Core did not confirm this draft');
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
for (const key of ['draft_order_id','run_id','event_id']) if (!uuid.test(result[key])) throw new Error('invalid bounded Core receipt');
return [{json:{status:result.status,draft_status:result.draft_status,external_order_reference:result.external_order_reference,draft_order_id:result.draft_order_id,run_id:result.run_id,event_id:result.event_id}}];
